function validate([startAt, moveCost, pushCost, targetSeconds]) {
  if (!Number.isInteger(startAt) || startAt < 0 || startAt > 9) return 'startAt is a digit from 0 to 9.';
  if (!Number.isInteger(moveCost) || moveCost < 1 || moveCost > 100000) return 'moveCost is between 1 and 10^5.';
  if (!Number.isInteger(pushCost) || pushCost < 1 || pushCost > 100000) return 'pushCost is between 1 and 10^5.';
  if (!Number.isInteger(targetSeconds) || targetSeconds < 1 || targetSeconds > 6039) return 'targetSeconds is between 1 and 6039.';
  return null;
}

