function minCostSetTime(startAt, moveCost, pushCost, targetSeconds) {
  let best = Infinity;

  for (let minutes = 0; minutes <= 99; minutes++) {
    const seconds = targetSeconds - minutes * 60;
    if (seconds < 0 || seconds > 99) {
      continue;
    }
    const digits = String(minutes * 100 + seconds);
    let finger = startAt;
    let cost = 0;
    for (const ch of digits) {
      const digit = Number(ch);
      if (digit !== finger) {
        cost += moveCost;
        finger = digit;
      }
      cost += pushCost;
    }
    best = Math.min(best, cost);
  }
  return best;
}

