function minCostSetTime(startAt, moveCost, pushCost, targetSeconds) {
  // Try every key sequence of length 1 to 4, leading zeros included.
  let best = Infinity;
  for (let length = 1; length <= 4; length++) {
    const limit = 10 ** length;
    for (let value = 0; value < limit; value++) {
      const typed = String(value).padStart(length, '0');
      const padded = typed.padStart(4, '0');
      const time = Number(padded.slice(0, 2)) * 60 + Number(padded.slice(2));
      if (time !== targetSeconds) continue;
      let cost = 0;
      let at = String(startAt);
      for (const key of typed) {
        if (key !== at) cost += moveCost;
        at = key;
        cost += pushCost;
      }
      if (cost < best) best = cost;
    }
  }
  return best;
}

