function generate(rand, size) {
  const pick = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const startAt = pick(0, 9);
  const top = size === 'large' || rand() < 0.3 ? 100000 : 10;
  const moveCost = pick(1, top);
  const pushCost = pick(1, top);
  const roll = rand();
  // Favour targets with two ways to write them (60 to 99 seconds past a minute) and the extremes.
  const targetSeconds = roll < 0.4 ? Math.min(6039, pick(1, 99) * 60 + pick(0, 39)) : roll < 0.5 ? pick(5980, 6039) : roll < 0.6 ? pick(1, 120) : pick(1, 6039);
  return [startAt, moveCost, pushCost, targetSeconds];
}
